"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { BellIcon } from "@/components/blocks/parts/icons";

import { BlockFrame } from "../parts/block-frame";
import { CardIcon, PersonIcon, ShieldIcon } from "./icons";
import { countChanges, NOTIFICATION_ROWS, SAVED, SECTIONS, SECURITY_ROWS, type SectionId, type SettingsForm } from "./settings-page/data";
import { ProfileSection } from "./settings-page/profile-section";
import { SaveBar } from "./settings-page/save-bar";
import { SectionNav } from "./settings-page/section-nav";
import { TextField } from "./settings-page/text-field";
import { ToggleSection } from "./settings-page/toggle-section";

const ICONS = { profile: PersonIcon, notifications: BellIcon, security: ShieldIcon, billing: CardIcon };

/**
 * Account settings in four sections. Editing any field brings up a save bar
 * that counts the pending changes; Save, or Command or Control with S while
 * focus is inside the block, stores them. Discard puts every field back.
 */
export function SettingsPage({ className }: { className?: string }) {
  const [active, setActive] = useState<SectionId>("profile");
  const [saved, setSaved] = useState<SettingsForm>(SAVED);
  const [form, setForm] = useState<SettingsForm>(SAVED);
  const [saving, setSaving] = useState(false);
  const [announce, setAnnounce] = useState("");
  const timer = useRef<number | null>(null);
  const titleId = useId();
  const panelId = useId();
  const reduceMotion = useReducedMotion();

  const changes = countChanges(form, saved);
  const section = SECTIONS.find((item) => item.id === active) ?? SECTIONS[0]!;
  const tabId = (id: SectionId) => `${panelId}-tab-${id}`;

  useEffect(() => () => {
    if (timer.current) window.clearTimeout(timer.current);
  }, []);

  const update = (patch: Partial<SettingsForm>) => {
    setForm((current) => ({ ...current, ...patch }));
    setAnnounce("");
  };

  const save = () => {
    if (changes === 0 || saving) return;
    setSaving(true);
    const next = form;
    timer.current = window.setTimeout(() => {
      setSaved(next);
      setSaving(false);
      setAnnounce(`${countChanges(next, saved)} changes saved.`);
    }, 900);
  };

  const discard = () => {
    setForm(saved);
    setAnnounce("Changes discarded.");
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "s") {
      event.preventDefault();
      save();
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className} onKeyDown={onKeyDown}>
      <header className="border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Account settings
        </h2>
        <p className="text-sm text-muted-foreground">Harbour Street Physio, on Fernhill</p>
      </header>

      <div className="grid grid-cols-1 @2xl:grid-cols-[13rem_1fr]">
        <div className="min-w-0 border-b border-border @2xl:border-r @2xl:border-b-0">
          <SectionNav sections={SECTIONS} icons={ICONS} active={active} onChange={setActive} tabId={tabId} panelId={panelId} />
        </div>

        <div className="relative flex min-h-128 min-w-0 flex-col">
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={active}
              id={panelId}
              role="tabpanel"
              aria-labelledby={tabId(active)}
              tabIndex={-1}
              initial={reduceMotion ? false : { opacity: 0, y: "0.375rem" }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: "-0.25rem" }}
              transition={{ duration: 0.16, ease: "easeOut" }}
              className="flex flex-1 flex-col gap-6 p-5 outline-none @2xl:p-6"
            >
              <div>
                <h3 className="text-lg font-semibold">{section.title}</h3>
                <p className="text-sm text-muted-foreground">{section.helper}</p>
              </div>
              {active === "profile" ? <ProfileSection form={form} onChange={update} /> : null}
              {active === "notifications" ? <ToggleSection rows={NOTIFICATION_ROWS} form={form} onChange={update} /> : null}
              {active === "security" ? <ToggleSection rows={SECURITY_ROWS} form={form} onChange={update} /> : null}
              {active === "billing" ? (
                <div className="grid gap-4 @lg:grid-cols-2">
                  <TextField label="Name on invoices" value={form.invoiceName} onChange={(invoiceName) => update({ invoiceName })} />
                  <TextField
                    label="Send invoices to"
                    type="email"
                    value={form.invoiceEmail}
                    helper="Your clinic plan renews on Dec 1."
                    onChange={(invoiceEmail) => update({ invoiceEmail })}
                  />
                </div>
              ) : null}
            </motion.div>
          </AnimatePresence>
          <div className="px-5 pb-1">
            <SaveBar changes={changes} saving={saving} onSave={save} onDiscard={discard} />
          </div>
          <p role="status" className="sr-only">
            {announce}
          </p>
        </div>
      </div>
    </BlockFrame>
  );
}

