/** The four sections of the account settings. */
export type SectionId = "profile" | "notifications" | "security" | "billing";

/** One section in the side list. */
export interface Section {
  id: SectionId;
  label: string;
  title: string;
  helper: string;
}

/** The sections in the order the list shows them. */
export const SECTIONS: Section[] = [
  { id: "profile", label: "Profile", title: "Your profile", helper: "Patients see your name and photo on booking pages and reminders." },
  { id: "notifications", label: "Notifications", title: "Notifications", helper: "Choose which events reach your inbox. Urgent changes always do." },
  { id: "security", label: "Security", title: "Security", helper: "Keep your account safe on shared front-desk computers." },
  { id: "billing", label: "Billing", title: "Billing details", helper: "These details print on every invoice Fernhill sends you." },
];

/** Every value the settings hold. A change counts against the saved copy. */
export interface SettingsForm {
  /** The colour of the photo, or null once it is removed. */
  photo: number | null;
  name: string;
  role: string;
  email: string;
  timeZone: string;
  newBooking: boolean;
  cancellation: boolean;
  dailyAgenda: boolean;
  productNews: boolean;
  signInAlerts: boolean;
  lockAfterIdle: boolean;
  invoiceName: string;
  invoiceEmail: string;
}

/** The values as last saved. */
export const SAVED: SettingsForm = {
  photo: 0,
  name: "Amara Osei",
  role: "Practice manager",
  email: "amara@harbourstreet.clinic",
  timeZone: "Europe/London",
  newBooking: true,
  cancellation: true,
  dailyAgenda: false,
  productNews: false,
  signInAlerts: true,
  lockAfterIdle: false,
  invoiceName: "Harbour Street Physio Ltd",
  invoiceEmail: "accounts@harbourstreet.clinic",
};

/** The fields that hold a yes or no. */
export type ToggleKey = "newBooking" | "cancellation" | "dailyAgenda" | "productNews" | "signInAlerts" | "lockAfterIdle";

/** One switch row. */
export interface ToggleRow {
  key: ToggleKey;
  label: string;
  helper: string;
}

/** The switch rows of the notifications section. */
export const NOTIFICATION_ROWS: ToggleRow[] = [
  { key: "newBooking", label: "New bookings", helper: "An email each time a patient books with you." },
  { key: "cancellation", label: "Cancellations", helper: "An email when a visit is cancelled or moved." },
  { key: "dailyAgenda", label: "Daily agenda", helper: "Tomorrow's visits, sent at 6 pm." },
  { key: "productNews", label: "Product news", helper: "A short note when Fernhill adds something new." },
];

/** The switch rows of the security section. */
export const SECURITY_ROWS: ToggleRow[] = [
  { key: "signInAlerts", label: "Sign-in alerts", helper: "An email when your account signs in from a new device." },
  { key: "lockAfterIdle", label: "Lock after 10 minutes", helper: "Ask for your password again after 10 idle minutes." },
];

/** The time zones the picker offers. */
export const TIME_ZONES = [
  { value: "Europe/London", label: "London (GMT)" },
  { value: "Europe/Dublin", label: "Dublin (GMT)" },
  { value: "Europe/Lisbon", label: "Lisbon (WET)" },
  { value: "Europe/Amsterdam", label: "Amsterdam (CET)" },
  { value: "America/Toronto", label: "Toronto (EST)" },
];

/** The photo colours a change cycles through. */
export const PHOTO_TONES = ["bg-chart-1", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"];

/** How many fields differ from the saved copy. */
export function countChanges(form: SettingsForm, saved: SettingsForm) {
  // SAFETY: `saved` is a SettingsForm literal with no extra keys, so every key it lists is a form field.
  return (Object.keys(saved) as (keyof SettingsForm)[]).filter((key) => form[key] !== saved[key]).length;
}

/** The initials of a name, such as "AO". */
export function initials(name: string) {
  return (
    name
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toUpperCase())
      .join("") || "?"
  );
}

"use client";

import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";

import { PersonIcon } from "../icons";
import { initials, PHOTO_TONES, type SettingsForm, TIME_ZONES } from "./data";
import { TextField } from "./text-field";

/** Props for the profile section. */
export interface ProfileSectionProps {
  form: SettingsForm;
  onChange: (patch: Partial<SettingsForm>) => void;
}

/**
 * The photo with change and remove, then name, role, email and time zone.
 * Our sample has no upload, so Change picks the next photo colour.
 */
export function ProfileSection({ form, onChange }: ProfileSectionProps) {
  const zoneId = useId();
  const hasPhoto = form.photo !== null;
  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-wrap items-center gap-4">
        <span
          aria-hidden="true"
          className={cn(
            "flex size-16 shrink-0 items-center justify-center rounded-full text-xl font-semibold motion-safe:transition-colors",
            hasPhoto ? `${PHOTO_TONES[form.photo ?? 0]} text-primary-foreground` : "border border-dashed border-border text-muted-foreground",
          )}
        >
          {hasPhoto ? initials(form.name) : <PersonIcon className="size-6" />}
        </span>
        <div className="flex flex-col gap-2">
          <p className="text-sm text-muted-foreground">{hasPhoto ? "Square photos work best." : "No photo. Patients see your initials."}</p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => onChange({ photo: ((form.photo ?? -1) + 1) % PHOTO_TONES.length })}
            >
              Change photo
            </Button>
            <Button variant="ghost" size="sm" disabled={!hasPhoto} onClick={() => onChange({ photo: null })}>
              Remove
            </Button>
          </div>
        </div>
      </div>

      <div className="grid gap-4 @lg:grid-cols-2">
        <TextField label="Full name" value={form.name} autoComplete="name" onChange={(name) => onChange({ name })} />
        <TextField label="Role" value={form.role} autoComplete="organization-title" onChange={(role) => onChange({ role })} />
        <TextField
          label="Email"
          type="email"
          value={form.email}
          autoComplete="email"
          helper="Reminders and receipts come from this address."
          onChange={(email) => onChange({ email })}
        />
        <div className="flex min-w-0 flex-col gap-1.5">
          <label id={zoneId} className="text-sm font-medium">
            Time zone
          </label>
          <Select value={form.timeZone} onValueChange={(timeZone) => onChange({ timeZone })}>
            <SelectTrigger aria-labelledby={zoneId} className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {TIME_ZONES.map((zone) => (
                <SelectItem key={zone.value} value={zone.value}>
                  {zone.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">Your booking hours follow this zone.</p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useId } from "react";

import { Input } from "@/components/ui/input";

/** Props for one labelled text field. */
export interface TextFieldProps {
  label: string;
  value: string;
  onChange: (value: string) => void;
  helper?: string;
  type?: "text" | "email";
  autoComplete?: string;
}

/** A label, a text input and an optional helper line that the input points to. */
export function TextField({ label, value, onChange, helper, type = "text", autoComplete }: TextFieldProps) {
  const id = useId();
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <Input
        id={id}
        type={type}
        value={value}
        autoComplete={autoComplete}
        aria-describedby={helper ? `${id}-helper` : undefined}
        onChange={(event) => onChange(event.target.value)}
      />
      {helper ? (
        <p id={`${id}-helper`} className="text-xs text-muted-foreground">
          {helper}
        </p>
      ) : null}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

import { LoaderIcon } from "../icons";

/** Props for the bar that offers to save pending changes. */
export interface SaveBarProps {
  changes: number;
  saving: boolean;
  onSave: () => void;
  onDiscard: () => void;
}

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/**
 * Rises in once a setting changes, with the number of pending changes rolling
 * as it moves. Under reduced motion it appears in place.
 */
export function SaveBar({ changes, saving, onSave, onDiscard }: SaveBarProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {changes > 0 || saving ? (
        <motion.div
          key="save-bar"
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: "0.75rem", scale: 0.94 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: "0.75rem", scale: 0.94 }}
          transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 480, damping: 38 }}
          className="sticky bottom-3 z-10 mx-auto flex w-full max-w-lg flex-wrap items-center justify-between gap-3 rounded-xl border border-border bg-popover px-4 py-2.5 text-popover-foreground shadow-lg backdrop-blur-md"
        >
          <p className="text-sm">
            {saving ? (
              "Saving your changes"
            ) : (
              <>
                <NumberTicker value={changes} format={WHOLE} className="font-semibold" /> unsaved {changes === 1 ? "change" : "changes"}
              </>
            )}
          </p>
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={onDiscard} disabled={saving}>
              Discard
            </Button>
            <Button size="sm" onClick={onSave} disabled={saving} aria-keyshortcuts="Control+S Meta+S">
              {saving ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : null}
              Save
            </Button>
          </div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ComponentType, type SVGProps, useRef } from "react";

import { Button } from "@/components/ui/button";

import { focusRoving, rovingIndex } from "../shared/roving";
import type { Section, SectionId } from "./data";

/** Props for the side list of settings sections. */
export interface SectionNavProps {
  sections: Section[];
  icons: Record<SectionId, ComponentType<SVGProps<SVGSVGElement>>>;
  active: SectionId;
  onChange: (id: SectionId) => void;
  /** Builds the id of a section's tab and panel, so each names the other. */
  tabId: (id: SectionId) => string;
  panelId: string;
}

/**
 * The list of sections as a set of tabs. The highlight glides to the chosen
 * tab, or jumps there under reduced motion. Arrows move and choose, Home and
 * End go to the ends. On a narrow frame the list runs across the top.
 */
export function SectionNav({ sections, icons, active, onChange, tabId, panelId }: SectionNavProps) {
  const listRef = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const activeIndex = sections.findIndex((section) => section.id === active);

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Settings sections"
      aria-orientation="vertical"
      className="flex scroll-fade-effect-x scrollbar-none gap-1 overflow-x-auto p-3 @2xl:mask-none @2xl:flex-col @2xl:overflow-visible"
      onKeyDown={(event) => {
        const next = rovingIndex(event, activeIndex, sections.length);
        const section = next === null ? undefined : sections[next];
        if (next === null || !section) return;
        event.preventDefault();
        onChange(section.id);
        focusRoving(listRef.current, next);
      }}
    >
      {sections.map((section, index) => {
        const Icon = icons[section.id];
        const selected = section.id === active;
        return (
          <Button
            key={section.id}
            id={tabId(section.id)}
            role="tab"
            variant={selected ? "ghost" : "ghost"}
            aria-selected={selected}
            aria-controls={panelId}
            tabIndex={selected ? 0 : -1}
            data-roving={index}
            onClick={() => onChange(section.id)}
            className="relative isolate shrink-0 justify-start @2xl:w-full"
          >
            {selected ? (
              <motion.span
                layoutId={`${panelId}-glide`}
                aria-hidden="true"
                className="absolute inset-0 -z-10 rounded-lg bg-muted"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 520, damping: 42 }}
              />
            ) : null}
            <Icon aria-hidden="true" className="size-4" />
            {section.label}
          </Button>
        );
      })}
    </div>
  );
}

import type { KeyboardEvent } from "react";

/** Which arrow keys step through a list. */
export type RovingAxis = "vertical" | "horizontal" | "both";

const BACK = { vertical: ["ArrowUp"], horizontal: ["ArrowLeft"], both: ["ArrowUp", "ArrowLeft"] } as const;
const FORWARD = { vertical: ["ArrowDown"], horizontal: ["ArrowRight"], both: ["ArrowDown", "ArrowRight"] } as const;

/**
 * Reads one key press on a list of `count` items and returns the index it
 * moves to, or null for a key the list does not handle. Arrows step and wrap
 * at the ends; Home and End go to the first and last item. The caller
 * prevents the default only when an index comes back.
 */
export function rovingIndex(event: KeyboardEvent, current: number, count: number, axis: RovingAxis = "both"): number | null {
  if (count === 0) return null;
  const back: readonly string[] = BACK[axis];
  const forward: readonly string[] = FORWARD[axis];
  if (back.includes(event.key)) return (current - 1 + count) % count;
  if (forward.includes(event.key)) return (current + 1) % count;
  if (event.key === "Home") return 0;
  if (event.key === "End") return count - 1;
  return null;
}

/** Moves focus to the element in `container` that carries `data-roving` equal to `index`, after React has painted. */
export function focusRoving(container: HTMLElement | null, index: number) {
  requestAnimationFrame(() => {
    container?.querySelector<HTMLElement>(`[data-roving="${index}"]`)?.focus();
  });
}

"use client";

import { useId } from "react";

import { Switch } from "@/components/motion/switch";

import type { SettingsForm, ToggleRow } from "./data";

/** Props for a list of switch rows. */
export interface ToggleSectionProps {
  rows: ToggleRow[];
  form: SettingsForm;
  onChange: (patch: Partial<SettingsForm>) => void;
}

/** A list of settings that each turn on or off, with a helper line under each label. */
export function ToggleSection({ rows, form, onChange }: ToggleSectionProps) {
  const baseId = useId();
  return (
    <ul className="flex flex-col gap-5">
      {rows.map((row) => {
        const id = `${baseId}-${row.key}`;
        return (
          <li key={row.key} className="flex items-center justify-between gap-4">
            <span className="flex min-w-0 flex-col gap-0.5">
              <label htmlFor={id} className="cursor-pointer text-sm font-medium">
                {row.label}
              </label>
              <span id={`${id}-helper`} className="text-xs text-muted-foreground">
                {row.helper}
              </span>
            </span>
            <Switch
              id={id}
              aria-describedby={`${id}-helper`}
              checked={form[row.key]}
              onCheckedChange={(value) => onChange({ [row.key]: value })}
            />
          </li>
        );
      })}
    </ul>
  );
}
